<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';
$q=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$sort=$_GET['sort']??'popular';$where=["t.visibility='public'","t.moderation_status='approved'","u.status='active'"];$params=[];
if($q!==''){$where[]='(t.title LIKE ? OR t.description LIKE ? OR t.tags LIKE ? OR u.name LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term,$term);}if($category!==''){$where[]='c.slug=?';$params[]=$category;}
$order=$sort==='latest'?'t.created_at DESC':($sort==='rating'?'rating_avg DESC, rating_count DESC':'(t.use_count+t.download_count+like_count*3) DESC,t.created_at DESC');
$sql='SELECT t.*,u.name author_name,u.username,u.is_verified,u.avatar,c.name category_name,c.icon,'.template_metrics_sql().' FROM twibbons t JOIN users u ON u.id=t.owner_id LEFT JOIN categories c ON c.id=t.category_id WHERE '.implode(' AND ',$where).' ORDER BY '.$order.' LIMIT 60';$stmt=$pdo->prepare($sql);$stmt->execute($params);$items=$stmt->fetchAll();$categories=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jelajahi Karya — Semarakin</title><meta name="description" content="Temukan karya kampanye visual terbaru dan terpopuler dari kreator Indonesia."><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head"><span class="eyebrow">Jelajahi karya</span><h1 class="page-title" style="margin-top:12px">Temukan kampanye yang berarti.</h1><p class="subtitle">Cari berdasarkan momen, kategori, atau kreator favoritmu.</p></div><form class="explore-toolbar"><input name="q" value="<?=e($q)?>" placeholder="Cari karya atau kreator…"><select name="sort"><option value="popular" <?=$sort==='popular'?'selected':''?>>Terpopuler</option><option value="latest" <?=$sort==='latest'?'selected':''?>>Terbaru</option><option value="rating" <?=$sort==='rating'?'selected':''?>>Rating terbaik</option></select><button class="btn btn-primary">Terapkan</button></form><div class="category-chips"><a class="<?=$category===''?'active':''?>" href="explore">Semua</a><?php foreach($categories as $cat):?><a class="<?=$category===$cat['slug']?'active':''?>" href="explore?category=<?=e($cat['slug'])?>"><?=e($cat['name'])?></a><?php endforeach?></div><div class="social-grid"><?php foreach($items as $item):require __DIR__.'/template-card.php';endforeach?></div><?php if(!$items):?><div class="empty">Belum ada karya yang cocok dengan pencarianmu.</div><?php endif?></main><footer class="footer">Semarakin · Produk digital dari Apins Digital</footer></body></html>
